676	/**
677	 * Builds a map from toolCallId → toolName by scanning all AI messages across
678	 * all namespaces in the accumulated message map.
679	 */
680	function buildToolCallIndex(
681	  nsMap: Map<NamespaceKey, MergedMessage[]>,
682	): Map<string, string> {
683	  const index = new Map<string, string>();
684	  for (const messages of nsMap.values()) {
685	    for (const msg of messages) {
686	      for (const tc of msg.tool_calls) {
687	        if (tc.id) {
688	          index.set(tc.id, tc.name);
689	        }
690	      }
691	    }
692	  }
693	  return index;
694	}
