696	/**
697	 * Builds a map from toolCallId → { toolName, content } by scanning all
698	 * ToolMessages across all namespaces.  Only stores entries for tools whose
699	 * rendering rule needs inline results (currently `execute` and `task`).
700	 */
701	function buildToolResultIndex(
702	  nsMap: Map<NamespaceKey, MergedMessage[]>,
703	  toolCallIndex: Map<string, string>,
704	): Map<string, { toolName: string; content: string }> {
705	  const INLINE_RESULT_TOOLS = new Set(['execute', 'task']);
706	  const index = new Map<string, { toolName: string; content: string }>();
707	
708	  for (const messages of nsMap.values()) {
709	    for (const msg of messages) {
710	      const msgType = msg.type.toLowerCase();
711	      if (msgType !== 'tool' && msgType !== 'toolmessage') continue;
712	      const tcId = msg.tool_call_id;
713	      if (!tcId) continue;
714	
715	      const toolName = toolCallIndex.get(tcId);
716	      if (!toolName || !INLINE_RESULT_TOOLS.has(toolName)) continue;
717	
718	      const content = renderContent(msg.content);
719	      index.set(tcId, { toolName, content });
720	    }
721	  }
722	  return index;
723	}
