 877	/**
 878	 * Formats contextual `↳ …` detail lines for `ledger_*` tools.
 879	 *
 880	 * Tools are split into mutation and query families; each has its own detail
 881	 * format.  Unrecognised ledger tools emit no detail line (but the header is
 882	 * always emitted by the caller).
 883	 */
 884	function formatLedgerToolDetail(name: string, args: unknown): string[] {
 885	  const a = (args && typeof args === 'object' && !Array.isArray(args))
 886	    ? (args as Record<string, unknown>)
 887	    : {};
 888	
 889	  const wp = typeof a['work_package_id'] === 'string' ? a['work_package_id'] : '';
 890	
 891	  switch (name) {
 892	    // --- Mutation tools ---
 893	    case 'ledger_begin_work':
 894	    case 'ledger_start_pipeline': {
 895	      const type = typeof a['type'] === 'string' ? a['type'] : '';
 896	      const role = typeof a['agent_role'] === 'string' ? a['agent_role'] : '';
 897	      if (!wp) return [];
 898	      return [`↳ ${wp} — ${type} (${role})`];
 899	    }
 900	
 901	    case 'ledger_complete_pipeline': {
 902	      const type = typeof a['type'] === 'string' ? a['type'] : '';
 903	      const status = typeof a['status'] === 'string' ? a['status'] : '';
 904	      if (!wp) return [];
 905	      const detail = [`↳ ${wp} ${type} → ${status}`];
 906	      // Append first summary bullet if available.
 907	      const summary = a['summary'];
 908	      let firstItem: string | null = null;
 909	      if (typeof summary === 'string' && summary.trim()) {
 910	        firstItem = summary.trim().split('\n')[0] ?? null;
 911	      } else if (Array.isArray(summary) && summary.length > 0) {
 912	        const first = summary[0];
 913	        if (typeof first === 'string' && first.trim()) firstItem = first.trim();
 914	      }
 915	      if (firstItem) detail.push(`↳ ${firstItem}`);
 916	      return detail;
 917	    }
 918	
 919	    case 'ledger_cancel_pipeline': {
 920	      const type = typeof a['type'] === 'string' ? a['type'] : '';
 921	      const reason = typeof a['reason'] === 'string' ? a['reason'] : '';
 922	      if (!wp) return [];
 923	      return [`↳ ${wp} ${type} — ${reason}`];
 924	    }
 925	
 926	    case 'ledger_claim_work_package': {
 927	      const agent = typeof a['agent'] === 'string' ? a['agent'] : '';
 928	      if (!wp) return [];
 929	      return [`↳ ${wp} → ${agent}`];
 930	    }
 931	
 932	    case 'ledger_update_work_package_status': {
 933	      const status = typeof a['status'] === 'string' ? a['status'] : '';
 934	      if (!wp) return [];
 935	      return [`↳ ${wp} → ${status}`];
 936	    }
 937	
 938	    case 'ledger_update_pipeline_progress': {
 939	      const type = typeof a['type'] === 'string' ? a['type'] : '';
 940	      const summary = a['summary'];
 941	      let firstItem = '';
 942	      if (typeof summary === 'string') firstItem = summary.trim().split('\n')[0] ?? '';
 943	      else if (Array.isArray(summary) && summary.length > 0) {
 944	        const first = summary[0];
 945	        if (typeof first === 'string') firstItem = first.trim();
 946	      }
 947	      if (!wp) return [];
 948	      return [`↳ ${wp} ${type} — ${firstItem}`];
 949	    }
 950	
 951	    case 'ledger_update_acceptance_criteria': {
 952	      const ops = a['operations'];
 953	      const n = Array.isArray(ops) ? ops.length : 0;
 954	      if (!wp) return [];
 955	      return [`↳ ${wp} (${n} operations)`];
 956	    }
 957	
 958	    case 'ledger_add_project_comment': {
 959	      const type = typeof a['type'] === 'string' ? a['type'] : '';
 960	      const priority = typeof a['priority'] === 'string' ? a['priority'] : '';
 961	      const note = typeof a['note'] === 'string' ? a['note'] : '';
 962	      const firstNoteLine = note.split('\n')[0] ?? '';
 963	      return [`↳ ${type} (${priority}): ${firstNoteLine}`];
 964	    }
