1190	  if (mainMessages && mainMessages.length > 0) {
1191	    lines.push(...renderDialogueNamespaceBlock('', mainMessages, toolResultIndex, false));
1192	  }
1193	
1194	  for (const [nsKey, messages] of nsMap.entries()) {
1195	    if (nsKey === '') continue;
